      writer.stack[writer.stackSize - 1] = nonemptyDocument;
      return;
    }
    if (context == 1) {
      writer.stack[writer.stackSize - 1] = 2;
      if (writer.indent != null) {
        writer.out.write('\n');
        for (int i = 1, size = writer.stackSize; i < size; i++) {
          writer.out.write(writer.indent);
        }
